"""Generate_esp_sa"""
from builtins import object
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.connection_manager.communicator import Communicator
import re
import os
from sshtunnel import SSHTunnelForwarder
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class generate_esp_sa(object):
    """Generate_esp_sa"""
    def __init__(self):
        self.ip_x_s_regexp = r'src\s+(.*?)\s+dst\s+(.*?)\s+.*?esp\s+spi\s+(0x[a-f0-9]+)\s+.*?' \
                             r'auth-trunc\s+(\S+)\s+(0x[0-f0-9]+)\s+\d+\s+enc\s+(\S+)\s+(0x[a-f0-9]+)'

        pass

    def generate_esp_sa_key_file(self, wireshark_host, esp_sa_file):
        """
        Genearte Esp
        :param wireshark_host: host name in testline_config.json in which the decryption must
        happen, can be bts or secure_gw
        :param esp_sa_file : file location
        :param auth : auth protocol used  to decryption
        :param enc : Enc protocol used to decryption
        :return:
        """
        ipxscommand = "ip x s"
        spi_file = 'execution_logs/{}_spi'.format(get_config_variable(["bts_id"]))
        if not os.path.exists(os.path.dirname(spi_file)):
            os.makedirs(os.path.dirname(spi_file))

        enb_data, status = self._execute_command_on_bts(wireshark_host, ipxscommand)

        if status or enb_data == '':
            logger.error("Command {} Execution Failed\n".format(ipxscommand))
            logger.debug(enb_data)
            raise Exception("Execution of command failed due to {}".format(enb_data))

        ip_x_s_match_obj = re.finditer(self.ip_x_s_regexp, enb_data, re.MULTILINE | re.DOTALL)
        with open(esp_sa_file, "a") as wireshark_file:
            for tunnel_match in ip_x_s_match_obj:
                wireshark_file.write('"{0}","{1}","{2}","{3}","{4}","{5}","{6}","{7}"\n'.format(
                    generate_esp_sa._get_ip_version(tunnel_match.group(1)),
                    tunnel_match.group(1),
                    tunnel_match.group(2),
                    tunnel_match.group(3),
                    get_config_variable(["ipsec", "enc", tunnel_match.group(6)]),
                    tunnel_match.group(7),
                    get_config_variable(["ipsec", "auth", tunnel_match.group(4)]),
                    tunnel_match.group(5)))
        with open(spi_file, "w") as spi_file:
            spi_file.write(enb_data)

    @staticmethod
    def _get_ip_version(ip_address):
        if re.search(r'(\d+\.){3}\d+', ip_address):
            return "IPv4"
        else:
            return "IPv6"

    def _execute_command_on_bts(self, host_section, cmd):
        ip = get_config_variable([host_section, "ip"])
        user = get_config_variable([host_section, "user"])
        password = get_config_variable([host_section, "password"])
        remote_lmp_ip = get_config_variable([host_section, "remote_lmp_ip"])
        remote_lmp_user = get_config_variable([host_section, "remote_lmp_user"])
        remote_lmp_pwd = get_config_variable([host_section, "remote_lmp_pwd"])

        if remote_lmp_ip:
            logger.info("Chained Setup")
            with SSHTunnelForwarder((remote_lmp_ip, 22),
                                    ssh_username=remote_lmp_user, ssh_password=remote_lmp_pwd,
                                    remote_bind_address=(ip, 22),
                                    local_bind_address=('0.0.0.0', 10022)):
                enb_data, status = Communicator().execute_command_remotely_and_verify('0.0.0.0',
                                                                                      user,
                                                                                      password,
                                                                                      cmd,
                                                                                      port=10022)
        else:
            logger.info("Not Chained Setup")
            enb_data, status = Communicator().execute_command_remotely_and_verify(ip, user,
                                                                                  password, cmd)
        return enb_data, status
